require_once __DIR__ . '/../includes/admin_layout.php';
require_admin();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$category = $id ? (static function(int $id): ?array { $s = db()->prepare('SELECT * FROM categories WHERE id=?'); $s->execute([$id]); return $s->fetch() ?: null; })($id) : null;
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $id = filter_input(INPUT_POST, 'id', FILTER_VALIDATE_INT) ?: 0; $name = trim((string) ($_POST['name'] ?? '')); $slug = slugify((string) ($_POST['slug'] ?? $name)); $sort = filter_input(INPUT_POST, 'sort_order', FILTER_VALIDATE_INT) ?: 0; if (!$name || !$slug) { $error = 'Name and slug are required.'; } else { try { $values = [$slug, $name, $sort, isset($_POST['is_active']) ? 1 : 0]; if ($id) { $values[] = $id; db()->prepare('UPDATE categories SET slug=?, name=?, sort_order=?, is_active=? WHERE id=?')->execute($values); } else { db()->prepare('INSERT INTO categories (slug,name,sort_order,is_active) VALUES (?,?,?,?)')->execute($values); } redirect('admin/categories.php'); } catch (Throwable $exception) { $error = 'Could not save this category. Check that the slug is unique.'; } } }
$category = $category ?: ['name'=>'','slug'=>'','sort_order'=>0,'is_active'=>1]; admin_header($id ? 'Edit category' : 'Add category'); ?><form class="admin-card" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($id) ?>"><?php if ($error): ?><div class="alert"><?= e($error) ?></div><?php endif; ?><div class="form-grid"><div class="field"><label for="name">Category name</label><input id="name" name="name" value="<?= e($category['name']) ?>" required></div><div class="field"><label for="slug">Slug</label><input id="slug" name="slug" value="<?= e($category['slug']) ?>" required></div><div class="field"><label for="sort_order">Sort order</label><input id="sort_order" name="sort_order" type="number" value="<?= e($category['sort_order']) ?>"></div><div class="field"><label><input type="checkbox" name="is_active" value="1"<?= $category['is_active'] ? ' checked' : '' ?>> Visible in catalog</label></div></div><div class="form-actions"><button class="button button-dark">Save category</button><a class="button" href="<?= e(app_url('admin/categories.php')) ?>">Cancel</a></div></form><?php admin_footer(); ?>
